// Old databases created before the dxwatch switch lack spot_id.
// Add it once; on newer schemas run a harmless no-op instead.
const rows = msg.payload;
const has = Array.isArray(rows) && rows.length > 0 && Number(rows[0].c) > 0;
msg.topic = has ? 'SELECT 1' : 'ALTER TABLE spots ADD COLUMN spot_id INTEGER';
return msg;

const lastId = flow.get('lastSpotId') || 0;
msg.url = 'https://dxwatch.com/dxsd1/s.php?s=' + lastId + '&r=200&d=1';
msg.headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
    'Accept': 'application/json, text/javascript, */*; q=0.01',
    'Referer': 'https://dxwatch.com/',
    'X-Requested-With': 'XMLHttpRequest'
};
return msg;

const call = encodeURIComponent(String(msg.payload.call || '').toUpperCase());
msg.backfillCall = String(msg.payload.call || '').toUpperCase();
msg.payload = '';
msg.url = 'https://dxwatch.com/dxsd1/s.php?s=0&r=200&d=1&cdx=' + call;
msg.headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
    'Accept': 'application/json, text/javascript, */*; q=0.01',
    'Referer': 'https://dxwatch.com/',
    'X-Requested-With': 'XMLHttpRequest'
};
return msg;

let json = msg.payload;
if (typeof json === 'string') {
    try { json = JSON.parse(json); }
    catch (e) { node.warn('dxwatch: response is not valid JSON'); return null; }
}
if (!json || !json.s) return null;

const monitored = (global.get('monitoredCalls') || []).map(c => String(c).toUpperCase());
const homeLat = parseFloat(global.get('homelat'));
const homeLon = parseFloat(global.get('homelon'));
const homeOk = !isNaN(homeLat) && !isNaN(homeLon);
const isBackfill = !!msg.backfillCall;
const nowSec = Date.now() / 1000;

function hav(la1, lo1, la2, lo2) {
    const R = 6371;
    const r = d => d * Math.PI / 180;
    const dLa = r(la2 - la1), dLo = r(lo2 - lo1);
    const a = Math.sin(dLa/2)*Math.sin(dLa/2) +
              Math.cos(r(la1))*Math.cos(r(la2))*Math.sin(dLo/2)*Math.sin(dLo/2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}
function unesc(s) {
    return String(s)
        .replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"')
        .replace(/&#39;|&apos;/g,"'").replace(/&amp;/g,'&');
}
function modeOf(c0) {
    const c = String(c0).toUpperCase();
    if (/\bCW\b/.test(c)) return 'CW';
    if (/FT8|FT4|RTTY|PSK|JT65|JT9|JS8|MFSK|OLIVIA|CONTESTIA|DOMINO|HELL|THOR|THROB/.test(c)) return 'DIGI';
    if (/\b(SSB|USB|LSB|AM|FM|PHONE)\b/.test(c)) return 'PHONE';
    return null;
}

const seen = flow.get('seenIds') || {};
const dedup = flow.get('dedupKeys') || {};
let lastId = flow.get('lastSpotId') || 0;
const records = [];
let added = 0;

for (const idStr of Object.keys(json.s)) {
    const id = parseInt(idStr, 10);
    if (!id || seen[id]) continue;
    const row = json.s[idStr];
    if (!Array.isArray(row)) continue;

    const de = String(row[0] || '').trim().toUpperCase();
    const freq = parseFloat(row[1]);
    const target = String(row[2] || '').trim().toUpperCase();
    const comment = unesc(row[3] == null ? '' : row[3]);
    const spotTime = String(row[4] || '');
    const ageSec = parseInt(row[5], 10);

    if (!de || !target || isNaN(ageSec) || ageSec < 0) continue;
    if (!monitored.includes(target)) continue;

    // Backfill: keep at most 7 days / 150 spots
    if (isBackfill && (ageSec / 86400 > 7 || added >= 150)) continue;

    // Spotter (DE) coordinates from the inline ci object - no external lookup
    const ci = json.ci || {};
    const deInfo = ci[de] || [];
    let lat = parseFloat(deInfo[6]); if (isNaN(lat)) lat = null;
    let lon = parseFloat(deInfo[7]); if (isNaN(lon)) lon = null;

    let distKm = null;
    if (lat !== null && lon !== null && homeOk) distKm = hav(homeLat, homeLon, lat, lon);

    // FT8-style reports: prefer 'Rcvd: -15' (target as heard by spotter), else '-8 dB'
    let snr = null;
    const rcvd = comment.match(/Rcvd:\s*([+-]?\d+)/i);
    const dbm  = comment.match(/([+-]?\d+)\s*dB/i);
    const sm = rcvd || dbm;
    if (sm) snr = parseInt(sm[1], 10);

    let signal = null;
    const rst = comment.match(/\b([1-5][1-9]{2})\b/);
    if (rst) signal = rst[1];

    const dKey = target + '|' + de.replace(/-\d+$/, '') + '|' + Math.round(isNaN(freq) ? 0 : freq) + '|' + Math.floor((nowSec - ageSec) / 180);
    if (dedup[dKey]) { seen[id] = 1; if (!isBackfill && id > lastId) lastId = id; continue; }
    records.push({
        spot_id: id,
        timestamp: new Date((nowSec - ageSec) * 1000).toISOString(),
        monitored_call: target,
        de: de,
        freq: isNaN(freq) ? null : freq,
        spot_call: target,
        comment: comment,
        spot_time: spotTime,
        mode: modeOf(comment),
        signal: signal,
        snr: snr,
        lat: lat,
        lon: lon,
        distance_km: distKm === null ? null : Math.round(distKm),
        distance_miles: distKm === null ? null : Math.round(distKm * 0.62137)
    });
    seen[id] = 1;
    dedup[dKey] = nowSec;
    added++;
    if (!isBackfill && id > lastId) lastId = id;
}

// Keep the in-memory dedup map bounded
const idList = Object.keys(seen).map(Number);
if (idList.length > 2000) {
    idList.sort((a, b) => a - b);
    const keep = new Set(idList.slice(-2000));
    idList.forEach(k => { if (!keep.has(k)) delete seen[k]; });
}
flow.set('seenIds', seen);
for (const k of Object.keys(dedup)) { if (nowSec - dedup[k] > 900) delete dedup[k]; }
flow.set('dedupKeys', dedup);
if (!isBackfill) flow.set('lastSpotId', lastId);

if (!records.length) return null;
return records.map(r => ({payload: r}));

const s = msg.payload;
const esc = (v) => v === null || v === undefined ? 'NULL' : ("'" + String(v).replace(/'/g, "''") + "'");
const num = (v) => v === null || v === undefined || isNaN(v) ? 'NULL' : v;
msg.topic = `INSERT OR IGNORE INTO spots (spot_id, timestamp, monitored_call, de, freq, spot_call, comment, spot_time, mode, signal, snr, lat, lon, distance_km, distance_miles) VALUES (${num(s.spot_id)}, ${esc(s.timestamp)}, ${esc(s.monitored_call)}, ${esc(s.de)}, ${num(s.freq)}, ${esc(s.spot_call)}, ${esc(s.comment)}, ${esc(s.spot_time)}, ${esc(s.mode)}, ${esc(s.signal)}, ${num(s.snr)}, ${num(s.lat)}, ${num(s.lon)}, ${num(s.distance_km)}, ${num(s.distance_miles)});`;
return msg;

let calls = msg.payload;
if (typeof calls === 'string') {
    try { calls = JSON.parse(calls); } catch (e) { calls = calls.split(',').map(c => c.trim()).filter(Boolean); }
}
if (!Array.isArray(calls)) calls = [];
calls = calls.map(c => String(c).toUpperCase().trim()).filter(Boolean).slice(0, 9);

const prev = (global.get('monitoredCalls') || []).map(c => String(c).toUpperCase());
const fresh = calls.filter(c => !prev.includes(c));
global.set('monitoredCalls', calls);

// output 1: HTTP reply; output 2: one backfill request per newly added call
msg.headers = {'Content-Type': 'application/json'};
msg.payload = {success: true, calls: calls, backfill: fresh};
const backfillMsgs = fresh.map(c => ({payload: {call: c}}));
return [msg, backfillMsgs];

const call = msg.req.query.call;
const limit = parseInt(msg.req.query.limit) || 1000;
const esc = (v) => "'" + String(v).replace(/'/g, "''") + "'";
let sql = 'SELECT * FROM spots';
if (call) {
    const c = call.toUpperCase();
    sql += ' WHERE monitored_call = ' + esc(c) + ' OR spot_call = ' + esc(c);
}
sql += ' ORDER BY id DESC LIMIT ' + limit;
msg.topic = sql;
msg.headers = {'Content-Type': 'application/json'};
return msg;

msg.headers = {'Content-Type': 'application/json'};
msg.payload = {
    homelat: global.get('homelat') || '',
    homelon: global.get('homelon') || ''
};
return msg;

const cfg = msg.payload || {};
if (cfg.homelat !== undefined) global.set('homelat', String(cfg.homelat).trim());
if (cfg.homelon !== undefined) global.set('homelon', String(cfg.homelon).trim());
msg.headers = {'Content-Type': 'application/json'};
msg.payload = {success: true};
return msg;

msg.url = 'https://www.reversebeacon.net/main.php';
msg.headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
    'Accept': 'text/html,*/*;q=0.8'
};
return msg;

const m = String(msg.payload || '').match(/RBN_version_hash\s*=\s*"([0-9a-f]+)"/);
if (m) {
    flow.set('rbnH', m[1]);
    node.status({fill: 'green', shape: 'dot', text: 'h=' + m[1]});
} else {
    node.status({fill: 'red', shape: 'ring', text: 'hash not found'});
}
return null;

const h = flow.get('rbnH');
if (!h) return null; // version hash not fetched yet
const lastId = flow.get('lastRbnId') || 0;
msg.url = 'https://www.reversebeacon.net/spots.php?h=' + h + '&ma=36000&s=' + lastId + '&r=200';
msg.headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
    'Accept': 'application/json, text/javascript, */*; q=0.01',
    'Referer': 'https://www.reversebeacon.net/main.php',
    'X-Requested-With': 'XMLHttpRequest'
};
return msg;

// Non-200 (e.g. 400 when the version hash went stale): drop the hash
// and trigger a re-fetch of main.php via output 2.
if (msg.statusCode !== 200) {
    flow.set('rbnH', null);
    return [null, {payload: ''}];
}

let json = msg.payload;
if (typeof json === 'string') {
    try { json = JSON.parse(json); }
    catch (e) { node.warn('RBN: response is not valid JSON'); return null; }
}
if (!json || !json.spots) return null;

const monitored = (global.get('monitoredCalls') || []).map(c => String(c).toUpperCase());
const homeLat = parseFloat(global.get('homelat'));
const homeLon = parseFloat(global.get('homelon'));
const homeOk = !isNaN(homeLat) && !isNaN(homeLon);
const nowSec = Date.now() / 1000;

function hav(la1, lo1, la2, lo2) {
    const R = 6371;
    const r = d => d * Math.PI / 180;
    const dLa = r(la2 - la1), dLo = r(lo2 - lo1);
    const a = Math.sin(dLa/2)*Math.sin(dLa/2) +
              Math.cos(r(la1))*Math.cos(r(la2))*Math.sin(dLo/2)*Math.sin(dLo/2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const ci = json.call_info || {};
const dedup = flow.get('dedupKeys') || {};
let lastId = flow.get('lastRbnId') || 0;
if (json.lastid_c && json.lastid_c > lastId) lastId = json.lastid_c;
const records = [];

for (const idStr of Object.keys(json.spots)) {
    const id = parseInt(idStr, 10);
    if (!id) continue;
    if (id > lastId) lastId = id;
    const row = json.spots[idStr];
    if (!Array.isArray(row)) continue;

    // RBN row: [de(skimmer), freq kHz, dx call, snr dB, wpm, time str, ?, ?, ?, ?, epoch]
    const de = String(row[0] || '').trim().toUpperCase();
    const freq = parseFloat(row[1]);
    const target = String(row[2] || '').trim().toUpperCase();
    const snr = parseInt(row[3], 10);
    const wpm = parseInt(row[4], 10);
    const spotTime = String(row[5] || '');
    const epoch = parseInt(row[10], 10);

    if (!de || !target || isNaN(epoch)) continue;
    if (!monitored.includes(target)) continue;

    // Cross-source dedup: dxwatch may carry the same CW spot
    const dKey = target + '|' + de.replace(/-\d+$/, '') + '|' + Math.round(isNaN(freq) ? 0 : freq) + '|' + Math.floor(epoch / 180);
    if (dedup[dKey]) continue;

    // Skimmer (DE) coordinates from the inline call_info object
    const deInfo = ci[de] || ci[de.replace(/-\d+$/, '')] || [];
    let lat = parseFloat(deInfo[6]); if (isNaN(lat)) lat = null;
    let lon = parseFloat(deInfo[7]); if (isNaN(lon)) lon = null;

    let distKm = null;
    if (lat !== null && lon !== null && homeOk) distKm = hav(homeLat, homeLon, lat, lon);

    records.push({
        spot_id: -id, // negative namespace keeps RBN ids apart from dxwatch ids
        timestamp: new Date(epoch * 1000).toISOString(),
        monitored_call: target,
        de: de,
        freq: isNaN(freq) ? null : freq,
        spot_call: target,
        comment: 'CW' + (isNaN(wpm) ? '' : ' ' + wpm + ' WPM'),
        spot_time: spotTime,
        mode: 'CW',
        signal: null,
        snr: isNaN(snr) ? null : snr,
        lat: lat,
        lon: lon,
        distance_km: distKm === null ? null : Math.round(distKm),
        distance_miles: distKm === null ? null : Math.round(distKm * 0.62137)
    });
    dedup[dKey] = nowSec;
}

flow.set('lastRbnId', lastId);
for (const k of Object.keys(dedup)) { if (nowSec - dedup[k] > 900) delete dedup[k]; }
flow.set('dedupKeys', dedup);

if (!records.length) return null;
return [records.map(r => ({payload: r})), null];
